/// <reference path="./env.d.ts" />

/**
 * Web server for the Week 7 field guide.
 *
 * Week 6 used nginx to serve a folder of HTML, CSS, and JavaScript.
 * This file does that job with Bun. Bun also transpiles site/app.ts,
 * so the browser receives JavaScript and the class can write TypeScript directly.
 *
 * Students do not edit this file.
 *
 * development: true rebuilds the page assets when site/app.ts changes.
 * Save, then refresh the browser.
 *
 * hostname 0.0.0.0 matters inside Docker. The process must accept
 * connections forwarded from the host, not only from inside the container.
 */

import homepage from "./site/index.html";

const server = Bun.serve({
  hostname: "0.0.0.0",
  port: 3000,
  development: true,
  routes: {
    "/": homepage,
  },
});

console.log(`Serving ${server.url}`);
